import java.util.*;import java.util.concurrent.*;import java.math.BigDecimal;import org.springframework.context.annotation.AnnotationConfigApplicationContext;import org.springframework.jdbc.core.JdbcTemplate;import com.project.system.service.*;import com.project.web.controller.system.MerchantGatewayController;import com.fasterxml.jackson.databind.JsonNode;
public class ApiConcurrencyIntegration{public static void main(String[]args)throws Exception{try(AnnotationConfigApplicationContext c=new AnnotationConfigApplicationContext(MerchantApiIntegration.Config.class)){JdbcTemplate db=c.getBean(JdbcTemplate.class);MerchantApiService api=c.getBean(MerchantApiService.class);WalletService w=c.getBean(WalletService.class);MerchantGatewayController g=c.getBean(MerchantGatewayController.class);Map<String,Object> cred=db.queryForMap("select * from campus_api_credential order by merchant_id desc limit 1");long merchant=((Number)cred.get("merchant_id")).longValue(),user=merchant+1;api.configure(merchant,true,true,true,"",1);String id=(String)cred.get("public_id"),secret=(String)cred.get("secret"),card=db.queryForObject("select card_no from campus_card where user_id=?",String.class,user);Map<String,String> p=MerchantApiIntegration.payload(id,"接口测试商户","PAY","0.50",card);String order=MerchantApiIntegration.call(g,"orders",MerchantApiIntegration.json.writeValueAsString(p),id,secret).path("data").path("orderNo").asText();String serial="LOCAL"+UUID.randomUUID().toString();p.put("orderNo",order);p.put("localSerialNo",serial);String body=MerchantApiIntegration.json.writeValueAsString(p);BigDecimal before=(BigDecimal)w.info(user).get("balance");ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch ready=new CountDownLatch(2),start=new CountDownLatch(1);List<Future<JsonNode>> futures=new ArrayList<>();for(int i=0;i<2;i++)futures.add(pool.submit(()->{ready.countDown();start.await();return MerchantApiIntegration.call(g,"execute",body,id,secret);}));ready.await();start.countDown();String first=null;for(Future<JsonNode> f:futures){JsonNode result=f.get();if(!"SUCCESS".equals(result.path("code").asText()))throw new AssertionError(result.toString());String number=result.path("data").path("transactionNo").asText();if(first==null)first=number;else if(!first.equals(number))throw new AssertionError();}pool.shutdown();if(((BigDecimal)w.info(user).get("balance")).compareTo(before.subtract(new BigDecimal("0.50")))!=0)throw new AssertionError();System.out.println("PASS concurrent same-order requests debit once and return same ledger");Map<String,String> other=MerchantApiIntegration.payload(id,"接口测试商户","PAY","0.50",card);String second=MerchantApiIntegration.call(g,"orders",MerchantApiIntegration.json.writeValueAsString(other),id,secret).path("data").path("orderNo").asText();other.put("orderNo",second);other.put("localSerialNo",serial);JsonNode collision=MerchantApiIntegration.call(g,"execute",MerchantApiIntegration.json.writeValueAsString(other),id,secret);if(!"INVALID_REQUEST".equals(collision.path("code").asText()))throw new AssertionError(collision.toString());System.out.println("PASS reused local serial rejected across orders");String malformed="{\"merchantId\":\""+id+"\",\"amount\":\"1\",\"amount\":\"2\"}";if(!"INVALID_REQUEST".equals(MerchantApiIntegration.call(g,"orders",malformed,id,secret).path("code").asText()))throw new AssertionError();System.out.println("PASS duplicate JSON fields rejected");}}
}
